"use client";

// Generated by philote from page /services/new. Do not edit.
import { useActionState } from "react";

import type { FormState } from "@/lib/form";

import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";

import Counter from "@/components/common/counter";
import FormField from "@/components/common/form-field";
import SubmitButton from "@/components/common/submit-button";

export default function Form({
    action,
    initial,
}: {
    action: (state: FormState, data: FormData) => Promise<FormState>;
    initial: Record<string, string>;
    options: Record<string, never>;
}) {
    const [state, submit] = useActionState(action, {});
    const values = state.values ?? initial;
    return (
        <form key={state.attempt} action={submit} className="space-y-6">
            <FormField name="name" label={"Name"} issue={state.issues?.name}>
                <Input id="name" name="name" type="text" required maxLength={60} defaultValue={values.name} aria-invalid={!!state.issues?.name} />
                <Counter id="name" max={60} initial={(values.name ?? "").length} />
            </FormField>
            <FormField name="minutes" label={"Minutes"} issue={state.issues?.minutes}>
                <Input id="minutes" name="minutes" type="number" required min={10} max={240} defaultValue={values.minutes} aria-invalid={!!state.issues?.minutes} />
            </FormField>
            <FormField name="price" label={"Price"} issue={state.issues?.price}>
                <Input id="price" name="price" type="number" required min={0} max={1000} defaultValue={values.price} aria-invalid={!!state.issues?.price} />
            </FormField>
            <FormField name="about" label={"About"} issue={state.issues?.about}>
                <Textarea id="about" name="about" required maxLength={280} defaultValue={values.about} aria-invalid={!!state.issues?.about} />
                <Counter id="about" max={280} initial={(values.about ?? "").length} />
            </FormField>
            {state.error && <p role="alert" className="text-sm text-destructive">{state.error}</p>}
            <SubmitButton>Save</SubmitButton>
        </form>
    );
}
